f36ebba9c517df6c6e2446/content/books/zizhi-tongjian/vol-286/year-0947/part-03/sources/library/tongjian-286-947-jin-army/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003395；电子底本待考，分段待核", "id": "21c9ad89-1dce-55af-a80c-e80b4d8dee80"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李继勋（后蜀将领）", "aliases": ["李繼勳（後蜀將領）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀左千牛卫上将军。947年正月癸丑，孟昶任命他为秦州宣慰使。使用国别限定身份，暂未与后周宋初同名将领合并，生卒年未载。", "biography": null, "status": "draft", "id": "2524497d-8a5b-5e26-81cb-c5fc6e3b1d1f"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "刘晞", "aliases": ["劉晞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州人，在契丹曾任枢密使、同平章事及燕京留守。947年任西京留守，到洛阳后责斥奚王慢待赵在礼。与后晋官员刘昫字形、职务不同，暂不合并；生卒年未载。", "biography": null, "status": "draft", "id": "a5949823-5190-5e38-a780-eb04d4e680a5"}, {"name": "留珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律阮（兀欲）的弟弟。947年正月耶律德光任命他为义成节度使。原书仅给名留珪，不自行补姓及后世异名，生卒年未载。", "biography": null, "status": "draft", "id": "c4aba494-f6e4-5964-b5ff-c172780f8dd6"}, {"name": "郎五", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年正月耶律德光任命他为镇宁节度使。《资治通鉴》称其为族人，具体亲等未说明，不建立具体血缘关系；生卒年未载。", "biography": null, "status": "draft", "id": "e3f58742-cf58-5340-8710-12036d6edab3"}, {"name": "潘聿捻", "aliases": ["潘聿撚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律阮的姐夫。947年正月被任命为横海节度使，原文字形为潘聿撚，展示采用捻并保留原字别名。生卒年未载。", "biography": null, "status": "draft", "id": "a77d94bc-16d8-5e81-b7da-1ea58bd7fdcb"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "张彦超", "aliases": ["張彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张彦超，蔚州刺史、举城归契丹者。", "biography": null, "status": "draft", "id": "abfe6397-741d-5795-88f6-462c9ce4b3b1"}, {"name": "史佺", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年正月受耶律德光任命为彰义节度使，但史匡威拒绝交出该镇。本段未载史佺实际到任，生卒年未载。", "biography": null, "status": "draft", "id": "d99ffb4c-c288-57d3-ac7d-72cd34763bc5"}, {"name": "刘晏僧", "aliases": ["劉晏僧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹客省副使。947年正月被任命为忠武节度使，姓名中的僧字不作为宗教身份依据。生卒年未载。", "biography": null, "status": "draft", "id": "def4f8a8-41c8-50c9-b538-2a420816d28b"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "焦继勋", "aliases": ["焦繼勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋武德使。941年十一月受石重贵派遣，与张从恩、郭金海、陈思让领大梁兵讨伐安从进；旧史奏报中也列其参与唐州以南战役。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a397d94d-0b6a-5593-9f5e-c39132813767"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}, {"name": "史匡威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史建瑭的儿子。947年契丹进入大梁后，以彰义节度使身份据守泾州，拒绝服从契丹命令。生卒年未载。", "biography": null, "status": "draft", "id": "33a282a4-7b28-5de0-8277-87347a12c935"}, {"name": "赵在礼", "aliases": ["趙在禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：赵在礼。", "biography": null, "status": "draft", "id": "90ff68a5-70f2-5182-8802-93859bae2990"}, {"name": "李肃（晋昌节度副使）", "aliases": ["李肅（晉昌節度副使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年赵在礼入朝后，留在长安的部将作乱，他以晋昌节度副使身份平定叛乱。原文籍贯写建人，疑有缺字，未补成具体地名；暂未与936年单州刺史同名人合并，生卒年未载。", "biography": null, "status": "draft", "id": "b968dc74-a8d5-5cf5-b7a9-67006da04ac9"}, {"name": "刘继勋", "aliases": ["劉繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "汲县人，曾任淄州刺史。938年受石敬瑭派遣，将澶州迁到跨德胜津的位置，并迁移顿丘。生卒年未载。", "biography": null, "status": "draft", "id": "fd3230f3-a204-58a2-96b7-0e7419ac3864"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "述轧", "aliases": ["述軋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年耶律德光派他与奚王拽刺、高谟翰驻守洛阳。生卒年、具体家族未载。", "biography": null, "status": "draft", "id": "1ecc60de-19a4-506b-a5c6-e10933ad627e"}, {"name": "拽剌（西奚王）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "西奚王李绍威的儿子，在父亲去世后继位。耶律德光从上党北归时，他前往迎接并归降。", "biography": null, "status": "draft", "id": "4098a81e-f684-5a3e-a8d7-3bf67a400198"}, {"name": "高谟翰", "aliases": ["高謨翰", "高模翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高谟翰，契丹前锋将领。", "biography": null, "status": "draft", "id": "70516658-fa9a-5bd1-8a0a-55b9844d4772"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
